import { Box, Icon, Avatar, IconButton } from "@mui/material";

export default function AccountIcon() {
    return (
        <Box
            position="absolute"
            top="20px"
            right="40px"
        >
            <IconButton>
            <Avatar alt="Remy Sharp" src="/static/images/avatar/1.jpg" />
            </IconButton>
        </Box>
    )
}
